import type * as THREE from 'three';
import type { Vec3 } from '../contracts/math';
import { PARTICLE_POOL_CAPACITY, qualityProfile, volumeToGain } from '../core/QualitySettings';
import type { QualityLevel, QualityProfile } from '../core/QualitySettings';
import { ParticleManager } from './ParticleManager';
import type { ParticleColor } from './ParticleManager';

export type FeedbackEvent = 'shot' | 'bounce' | 'hazard' | 'holed';
export type HazardKind = 'water' | 'lava' | 'void' | 'reset-zone';

/** The slice of AudioManager the feedback layer needs; keeps tests free of Web Audio. */
export interface FeedbackAudioSink {
  play(id: string): boolean;
  setMasterVolume(volume: number): void;
}

/** Audio event ids, matching public/audio/manifest.json. */
export const FEEDBACK_SOUNDS = {
  shot: 'hit',
  bounce: 'wall-bounce',
  holed: 'hole',
} as const;

export const HAZARD_SOUNDS: Record<HazardKind, string> = {
  water: 'water',
  lava: 'lava',
  void: 'teleport',
  'reset-zone': 'teleport',
};

const HAZARD_COLORS: Record<HazardKind, ParticleColor> = {
  water: { r: 0.42, g: 0.72, b: 1 },
  lava: { r: 1, g: 0.44, b: 0.16 },
  void: { r: 0.66, g: 0.5, b: 1 },
  'reset-zone': { r: 0.66, g: 0.5, b: 1 },
};

const BOUNCE_COOLDOWN = 0.07;
const BOUNCE_MIN_SPEED = 1.2;
/** Cosine of the deflection that still counts as a bounce rather than a curve. */
const BOUNCE_MAX_COSINE = -0.25;

export interface FeedbackOptions {
  audio?: FeedbackAudioSink;
  quality?: QualityLevel | string;
  /** Menu volume slider, 0..100. */
  volume?: number;
  /** Injected pool; the system allocates its own when omitted. */
  particles?: ParticleManager;
  random?: () => number;
}

interface BurstSpec {
  position: Vec3;
  velocity: Vec3;
  color: ParticleColor;
  count: number;
  spread: number;
  spreadVelocity: number;
  lifetime: number;
  drag: number;
  gravity?: number;
}

/**
 * Impact speed of a wall hit, or undefined when the velocity change is not a bounce.
 * Rapier does not surface contact events here, so a hard horizontal direction flip
 * between two fixed steps is what marks an impact.
 */
export function detectBounce(previous: Vec3, current: Vec3, minSpeed = BOUNCE_MIN_SPEED): number | undefined {
  const previousSpeed = Math.hypot(previous.x, previous.z);
  const currentSpeed = Math.hypot(current.x, current.z);
  if (previousSpeed < minSpeed || currentSpeed < 1e-4) return undefined;
  const cosine = (previous.x * current.x + previous.z * current.z) / (previousSpeed * currentSpeed);
  return cosine <= BOUNCE_MAX_COSINE ? previousSpeed : undefined;
}

/**
 * Audio-visual feedback for gameplay beats: shots, wall hits, hazards and the cup.
 * Owns one particle pool and forwards the menu quality/volume settings into it.
 */
export class FeedbackSystem {
  readonly particles: ParticleManager;

  private profile: QualityProfile;
  private audio: FeedbackAudioSink | undefined;
  private readonly random: () => number;
  private readonly emitted = new Map<FeedbackEvent, number>();
  private readonly requests = new Map<string, number>();
  private readonly ownsParticles: boolean;
  private bounceClock = 0;
  private volume: number;
  private disposed = false;

  constructor(options: FeedbackOptions = {}) {
    this.profile = qualityProfile(options.quality);
    this.random = options.random ?? Math.random;
    this.audio = options.audio;
    this.volume = options.volume ?? 100;
    this.ownsParticles = options.particles === undefined;
    this.particles =
      options.particles ??
      new ParticleManager({ capacity: PARTICLE_POOL_CAPACITY, pointSize: 0.11, gravity: -7.5, opacity: 0.95 });
    this.audio?.setMasterVolume(volumeToGain(this.volume));
  }

  /** Pool render node; mount it once into the scene. */
  get points(): THREE.Object3D {
    return this.particles.points;
  }

  get quality(): QualityLevel {
    return this.profile.level;
  }

  get masterVolume(): number {
    return volumeToGain(this.volume);
  }

  get activeParticles(): number {
    return this.particles.activeCount;
  }

  get totalEmitted(): number {
    let total = 0;
    for (const count of this.emitted.values()) total += count;
    return total;
  }

  emittedFor(event: FeedbackEvent): number {
    return this.emitted.get(event) ?? 0;
  }

  /** How often a sound was requested, whether or not a buffer was loaded. */
  soundRequests(soundId: string): number {
    return this.requests.get(soundId) ?? 0;
  }

  setQuality(level: QualityLevel | string | undefined): QualityProfile {
    this.profile = qualityProfile(level);
    return this.profile;
  }

  setVolume(volume: number): void {
    this.volume = volume;
    this.audio?.setMasterVolume(volumeToGain(volume));
  }

  setAudio(audio: FeedbackAudioSink | undefined): void {
    this.audio = audio;
    audio?.setMasterVolume(volumeToGain(this.volume));
  }

  update(deltaSeconds: number): void {
    if (this.disposed) return;
    this.bounceClock = Math.max(0, this.bounceClock - Math.max(0, deltaSeconds));
    this.particles.update(deltaSeconds);
  }

  /** Putt released: a short turf puff plus the club sound. */
  shot(position: Vec3, power: number): void {
    const strength = Math.min(1, Math.max(0, power));
    this.burst('shot', {
      position: { x: position.x, y: position.y + 0.02, z: position.z },
      velocity: { x: 0, y: 1.1 + strength, z: 0 },
      color: { r: 0.85, g: 0.98, b: 0.9 },
      count: Math.round(6 + strength * 10),
      spread: 0.1,
      spreadVelocity: 0.9,
      lifetime: 0.35,
      drag: 2.4,
    });
    this.play(FEEDBACK_SOUNDS.shot);
  }

  /** Wall or obstacle hit; rate limited so a rattling ball does not machine-gun the mixer. */
  bounce(position: Vec3, impactSpeed: number): void {
    if (this.disposed || this.bounceClock > 0) return;
    this.bounceClock = BOUNCE_COOLDOWN;
    const strength = Math.min(1, Math.max(0, impactSpeed / 8));
    this.burst('bounce', {
      position: { x: position.x, y: position.y, z: position.z },
      velocity: { x: 0, y: 0.8 + strength, z: 0 },
      color: { r: 1, g: 0.93, b: 0.68 },
      count: Math.round(4 + strength * 8),
      spread: 0.08,
      spreadVelocity: 1.4,
      lifetime: 0.28,
      drag: 3,
    });
    this.play(FEEDBACK_SOUNDS.bounce);
  }

  /** Water, lava or a reset volume swallowed the ball. */
  hazard(position: Vec3, kind: HazardKind = 'void'): void {
    this.burst('hazard', {
      position: { x: position.x, y: position.y + 0.05, z: position.z },
      velocity: { x: 0, y: 2.4, z: 0 },
      color: HAZARD_COLORS[kind],
      count: 18,
      spread: 0.22,
      spreadVelocity: 1.6,
      lifetime: 0.6,
      drag: 1.4,
    });
    this.play(HAZARD_SOUNDS[kind]);
  }

  /** Ball captured by the cup: celebration burst plus the hole sound. */
  holed(position: Vec3, color?: ParticleColor): void {
    this.burst('holed', {
      position: { x: position.x, y: position.y + 0.06, z: position.z },
      velocity: { x: 0, y: 3.4, z: 0 },
      color: color ?? { r: 1, g: 0.86, b: 0.45 },
      count: 42,
      spread: 0.18,
      spreadVelocity: 2.2,
      lifetime: 0.9,
      drag: 0.9,
      gravity: -6,
    });
    this.play(FEEDBACK_SOUNDS.holed);
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    if (this.ownsParticles) this.particles.dispose();
    else this.particles.clear();
    this.audio = undefined;
  }

  private burst(event: FeedbackEvent, spec: BurstSpec): number {
    if (this.disposed) return 0;
    const scaled = Math.round(spec.count * this.profile.particleScale);
    const budget = Math.max(0, this.profile.particleBudget - this.particles.activeCount);
    const count = Math.min(scaled, budget);
    if (count <= 0) return 0;

    let emitted = 0;
    for (let index = 0; index < count; index += 1) {
      const spawn = {
        position: spec.position,
        velocity: this.jitterVelocity(spec.velocity, spec.spreadVelocity),
        color: spec.color,
        count: 1,
        spread: spec.spread,
        lifetime: spec.lifetime * (0.75 + this.random() * 0.5),
        drag: spec.drag,
        random: this.random,
      };
      emitted += this.particles.emit(spec.gravity === undefined ? spawn : { ...spawn, gravity: spec.gravity });
    }
    if (emitted > 0) this.emitted.set(event, this.emittedFor(event) + emitted);
    return emitted;
  }

  private jitterVelocity(base: Vec3, spread: number): Vec3 {
    return {
      x: base.x + (this.random() * 2 - 1) * spread,
      y: base.y + (this.random() * 2 - 1) * spread * 0.5,
      z: base.z + (this.random() * 2 - 1) * spread,
    };
  }

  private play(soundId: string): void {
    this.requests.set(soundId, this.soundRequests(soundId) + 1);
    this.audio?.play(soundId);
  }
}
